(function(){(()=>{"use strict";const e=(t,n,o,i,s,a)=>({g:t,p:n,n:o,f:i,how:s,ex:a});window.PhysicaRankPcJee={chapter:"Permutations and Combinations",secs:["Counting principles and factorials","Permutations","Combinations and selections","Circular arrangements","Distributions, groups and solutions"],table:[["n!","n \xD7 (n \u2212 1) \xD7 \u2026 \xD7 1, with 0! = 1"],["\u207FP\u1D63","n!/(n \u2212 r)! arrangements of r out of n"],["\u207FC\u1D63","n!/(r!(n \u2212 r)!) selections of r out of n"],["\u207FC\u1D63 = \u207FC\u2099\u208B\u1D63","symmetry"],["\u207FP\u1D63 = r!\xB7\u207FC\u1D63","arrangement = selection then ordering"]],formulas:[e("Counting principles and factorials",1,"Rule of sum and rule of product","if one job can be done in m ways OR another in n ways (not both), the total is m + n \xB7 if one job is done in m ways AND THEN another in n ways, the total is m \xD7 n \xB7 it extends to any number of jobs","Ask: are the choices either-or (add) or one after the other (multiply)? Split into cases when a condition changes the number of choices.","A number plate with 2 letters (26 choices each) then 3 digits (10 each): 26\xB2 \xD7 10\xB3 = 676000."),e("Counting principles and factorials",1,"Factorial and its use","n! = n(n \u2212 1)(n \u2212 2) \u2026 2\xB71 \xB7 0! = 1 \xB7 n! = n\xB7(n \u2212 1)! \xB7 n objects in a row can be arranged in n! ways","Reduce a ratio of factorials by cancelling the common part.","7!/5! = 7 \xD7 6 = 42."),e("Permutations",1,"Permutations \u207FP\u1D63","\u207FP\u1D63 = n!/(n \u2212 r)! = n(n \u2212 1)(n \u2212 2) \u2026 (n \u2212 r + 1) \xB7 \u207FP\u2099 = n! \xB7 with repetition allowed the number is n\u02B3 \xB7 a particular object included: r\xB7\u207F\u207B\xB9P\u1D63\u208B\u2081","Fill the places one by one and count the choices for each place from the left. Handle the most restricted place first.","4-digit numbers from the digits 1 to 5 with no repetition: \u2075P\u2084 = 120."),e("Permutations",1,"Arrangements of alike objects","n objects with p of one kind, q of another and r of a third: n!/(p! q! r!) \xB7 letters of a word: count total letters and the repeats","Divide n! by the factorial of the count of each repeated letter.","MISSISSIPPI: 11!/(4!\xB74!\xB72!) = 34650. APPLE: 5!/2! = 60."),e("Permutations",1,"Restrictions: together, apart, fixed places","r objects together: tie them as one block, arrange the block with the rest, then arrange inside: (n \u2212 r + 1)!\xB7r! \xB7 not together = total \u2212 together \xB7 for objects with no two together, arrange the others first and place these in the gaps","Choose between the block method (together) and the gap method (never together). Use the complement when it is shorter.","3 of 7 students together: 5!\xB73! = 720."),e("Permutations",1,"Numbers and words with conditions","a number is even if the last digit is even: fill the last place first \xB7 a number is divisible by 5 if it ends in 0 or 5 \xB7 divisible by 3 when the digit sum is a multiple of 3 \xB7 for numbers greater than a given number, count by the first digit and add","Fill the restricted place first, then the first place (it cannot be 0), then the rest.","4-digit even numbers from 1 to 5 with no repetition: 2 \xD7 4 \xD7 3 \xD7 2 = 48."),e("Combinations and selections",1,"Combinations \u207FC\u1D63","\u207FC\u1D63 = n!/(r!(n \u2212 r)!) \xB7 \u207FC\u1D63 = \u207FC\u2099\u208B\u1D63 \xB7 \u207FC\u1D63 + \u207FC\u1D63\u208B\u2081 = \u207F\u207A\xB9C\u1D63 \xB7 \u207FC\u2093 = \u207FC\u1D67 \u21D2 x = y or x + y = n \xB7 \u207FP\u1D63 = r!\xB7\u207FC\u1D63","Use combinations when only the group matters, not the order. Use the symmetry to make r the smaller number.","C(10, 3) = 120."),e("Combinations and selections",1,"Selections with conditions","p particular things always included: \u207F\u207B\u1D56C\u1D63\u208B\u209A \xB7 p particular things always excluded: \u207F\u207B\u1D56C\u1D63 \xB7 at least one: total \u2212 none \xB7 selection from different kinds is a product of the selections \xB7 all ways of selecting zero or more of n different things: 2\u207F (so at least one: 2\u207F \u2212 1)","Break the selection into groups (men, women) and multiply; add the cases when the condition has several possibilities.","Choose 5 of 9 with two fixed ones included: \u2077C\u2083 = 35; excluded: \u2077C\u2085 = 21."),e("Combinations and selections",1,"Geometrical counting","lines from n points, no three collinear: \u207FC\u2082 \xB7 triangles: \u207FC\u2083 \xB7 diagonals of an n-gon: \u207FC\u2082 \u2212 n \xB7 if m points are collinear subtract \u1D50C\u2082 (lines) or \u1D50C\u2083 (triangles) and add 1 for the line \xB7 parallelograms in a grid of m and n lines: \u1D50C\u2082\xB7\u207FC\u2082","Count all selections first and subtract those that are not valid because of collinearity.","An octagon has \u2078C\u2082 \u2212 8 = 20 diagonals and \u2078C\u2083 = 56 triangles from its vertices."),e("Circular arrangements",2,"Circular arrangements","n different objects in a circle: (n \u2212 1)! \xB7 if clockwise and anticlockwise are the same (necklace): (n \u2212 1)!/2 \xB7 r of n in a circle: \u207FP\u1D63/r \xB7 fix one object to break the symmetry","Fix one person and arrange the rest in a line. For a necklace or garland divide by 2.","6 people at a round table: 5! = 120."),e("Distributions, groups and solutions",1,"Non-negative solutions","x\u2081 + x\u2082 + \u2026 + x\u2096 = n has \u207F\u207A\u1D4F\u207B\xB9C\u2096\u208B\u2081 solutions in whole numbers \u2265 0 \xB7 for each x\u1D62 \u2265 1 it is \u207F\u207B\xB9C\u2096\u208B\u2081 \xB7 for a lower bound, subtract it first","Treat the n units as stars and k \u2212 1 bars to separate the k groups.","x + y + z = 10 has C(12, 2) = 66 whole-number solutions."),e("Distributions, groups and solutions",2,"Groups and distribution of objects","dividing m + n objects into groups of m and n: (m + n)!/(m! n!) \xB7 equal groups of size r (k groups): (kr)!/((r!)\u1D4F\xB7k!) if the groups are not named \xB7 multiply by k! if the groups go to different people \xB7 identical objects to different persons use the stars-and-bars rule","Decide whether the groups are named. Equal-size unnamed groups need the division by k!.","6 people into 3 unnamed pairs: 6!/(2!\xB3\xB73!) = 15."),e("Distributions, groups and solutions",2,"Derangements","number of arrangements of n objects with none in its own place: D\u2099 = n!(1 \u2212 1/1! + 1/2! \u2212 \u2026 + (\u22121)\u207F/n!) \xB7 D\u2082 = 1, D\u2083 = 2, D\u2084 = 9, D\u2085 = 44","Use inclusion and exclusion for small n, or the formula.","4 letters in 4 addressed envelopes, none correct: D\u2084 = 9.")],look:["rule of sum: either-or; rule of product: one after the other","\u207FP\u1D63 = n!/(n \u2212 r)!, \u207FC\u1D63 = n!/(r!(n \u2212 r)!), \u207FP\u1D63 = r!\xB7\u207FC\u1D63","alike objects: n!/(p!q!\u2026); together: block method; apart: gap method","circular: (n \u2212 1)!; non-negative solutions of x\u2081+\u2026+x\u2096 = n: \u207F\u207A\u1D4F\u207B\xB9C\u2096\u208B\u2081","at least one: total \u2212 none"],notes:[{h:"Counting",items:["Add for either-or, multiply for one-after-the-other.","n! arranges n different objects in a row.","Fill the most restricted place first."]},{h:"Permutations and combinations",items:["Order matters: \u207FP\u1D63. Order does not matter: \u207FC\u1D63.","\u207FP\u1D63 = r!\xB7\u207FC\u1D63.","For alike objects divide by the factorial of each repeat.","Together: tie as a block. Never together: use gaps, or total \u2212 together."]},{h:"Special counts",items:["Circular: (n \u2212 1)!, and (n \u2212 1)!/2 for a necklace.","Non-negative solutions of x\u2081 + \u2026 + x\u2096 = n: \u207F\u207A\u1D4F\u207B\xB9C\u2096\u208B\u2081.","Lines, triangles and diagonals: choose points, then subtract the collinear ones."]}],asked:[{t:"Arrangements of letters or digits",what:"A word or a set of digits is given with repeats and conditions. Count the arrangements or numbers.",steps:["Count the total objects and the repeats; start with n!/(p!q!\u2026).","Fill the restricted places first (last digit for even, first digit not 0).","For together or apart, use the block method or total \u2212 together."],ex:"MISSISSIPPI has 34650 arrangements.",tp:"pcb"},{t:"Selections and committees",what:"A group is chosen from several kinds of people or objects with conditions.",steps:["Choose from each kind and multiply the choices.","Add the cases when the condition allows several splits.","For at least one, use total \u2212 none."],ex:"5 of 9 with two fixed ones included: \u2077C\u2083 = 35.",tp:"pcs"},{t:"Geometrical counting",what:"Points, lines or a polygon are given. Count lines, triangles or diagonals.",steps:["Choose points: \u207FC\u2082 for lines, \u207FC\u2083 for triangles.","Subtract the lines or triangles lost to collinear points.","For diagonals of an n-gon use \u207FC\u2082 \u2212 n."],ex:"An octagon has 20 diagonals.",tp:"pcs"},{t:"Distributions and non-negative solutions",what:"Objects are shared among people, or the number of solutions of x\u2081 + \u2026 + x\u2096 = n is asked.",steps:["Identical objects: stars and bars, \u207F\u207A\u1D4F\u207B\xB9C\u2096\u208B\u2081.","Different objects: each object has a choice of person, so k\u207F (or use groups).","Adjust for lower bounds first."],ex:"x + y + z = 10 has 66 solutions.",tp:"pcd"}],guide:{intro:"Permutations and Combinations give 1 to 2 questions in JEE Mains in most years: an arrangement with a restriction, a selection with a condition, or a geometrical count. About 6 hours in 4 days is enough. The idea also feeds binomial theorem and probability.",plan:[["Day 1 \xB7 90 min","The two rules, factorials, \u207FP\u1D63 and the restriction methods."],["Day 2 \xB7 90 min","Arrangements of alike objects, numbers and words with conditions."],["Day 3 \xB7 90 min","\u207FC\u1D63, selections with conditions and geometrical counting."],["Day 4 \xB7 90 min","Circular arrangements, distributions, non-negative solutions; then Most asked and the PYQs."]],basics:["Factorials and simple fractions.","Divisibility rules for 2, 3, 5.","Basic geometry of lines and polygons.","Solving simple equations."],path:[{t:"Step 1 \xB7 Counting rules (Day 1)",d:"Learn the rules of sum and product, factorials and \u207FP\u1D63.",ready:"you can count the 4-digit numbers from 1 to 5 with no repetition in one line.",go:"formulas"},{t:"Step 2 \xB7 Arrangements (Day 2)",d:"Learn alike objects, together and apart, numbers with conditions.",ready:"you can find the arrangements of MISSISSIPPI and of 3 together out of 7.",go:"formulas"},{t:"Step 3 \xB7 Selections (Day 3)",d:"Learn \u207FC\u1D63, conditions, at least one, and geometry.",ready:"you can count the diagonals of an octagon and the committees with a fixed member.",go:"notes"},{t:"Step 4 \xB7 Special counts (Day 4)",d:"Circular arrangements, non-negative solutions and distributions; then try the PYQs.",ready:"you can find the solutions of x + y + z = 10 and the circular arrangements of 6 people.",go:"asked"}],think:["First decide: does the order matter (permutation) or not (combination)?","Fill the most restricted place first.","If the direct count is long, count the opposite and subtract."],watch:["Using \u207FP\u1D63 when the order does not matter.","Forgetting the first digit cannot be 0.","Counting an arrangement twice when objects are alike.","Missing the division by k! for unnamed equal groups."],myths:[["\u207FC\u1D63 and \u207FP\u1D63 are the same.","\u207FP\u1D63 = r!\xB7\u207FC\u1D63: arrangements count the order, selections do not."],["Circular arrangements of n people give n!.","Only one position is fixed to break the symmetry, so it is (n \u2212 1)!."]]}}})()})();
